Your expense tracker is below. Add an expense, see the month's total and category split, and set a budget to watch how much is left. It saves on this device when your app allows it.

```page
<!DOCTYPE html>
<html><head><meta charset="utf-8">
<style>
body{font-family:Segoe UI,Arial,sans-serif;margin:0;padding:14px;background:#f6f6f8;color:#222}
h2{margin:0 0 10px}
.card{background:#fff;border-radius:10px;padding:12px;margin-bottom:12px;box-shadow:0 1px 3px #0002}
.row{display:flex;gap:8px;flex-wrap:wrap;align-items:center}
input,select,button{padding:7px;border:1px solid #bbb;border-radius:6px;font-size:14px}
button{background:#2b6cb0;color:#fff;border:0;cursor:pointer}
button.x{background:#c53030;padding:3px 8px}
.big{font-size:26px;font-weight:600}
.bar{height:10px;background:#2b6cb0;border-radius:5px}
.track{background:#e2e8f0;border-radius:5px;margin:3px 0 8px}
.meter{height:12px;border-radius:6px;background:#38a169}
table{width:100%;border-collapse:collapse}
td{padding:5px 4px;border-bottom:1px solid #eee;font-size:14px}
.r{text-align:right}
.muted{color:#666;font-size:13px}
</style></head><body>
<h2>Monthly expenses</h2>

<div class="card">
<div class="row">
<label>Month <input type="month" id="mon"></label>
<label>Budget (₹) <input type="number" id="bud" style="width:110px" min="0"></label>
</div>
<div class="big" id="total">₹0</div>
<div class="muted" id="left"></div>
<div class="track"><div class="meter" id="meter" style="width:0"></div></div>
</div>

<div class="card">
<div class="row">
<input type="date" id="d">
<select id="c"><option>Food</option><option>Rent</option><option>Travel</option><option>Bills</option><option>Shopping</option><option>Health</option><option>Fun</option><option>Other</option></select>
<input id="n" placeholder="Note" style="flex:1;min-width:90px">
<input type="number" id="a" placeholder="₹ Amount" min="0" style="width:110px">
<button id="add">Add</button>
</div>
</div>

<div class="card"><b>By category</b><div id="cats" style="margin-top:8px"></div></div>
<div class="card"><b>This month's entries</b><table id="list"></table></div>

<script>
var KEY="foo_expenses_v1",data={items:[],budget:0};
try{var s=localStorage.getItem(KEY);if(s)data=JSON.parse(s)}catch(e){}
function save(){try{localStorage.setItem(KEY,JSON.stringify(data))}catch(e){}}
function inr(n){return "₹"+Math.round(n).toLocaleString("en-IN")}
var t=new Date().toISOString().slice(0,10);
var $=function(i){return document.getElementById(i)};
$("d").value=t;$("mon").value=t.slice(0,7);$("bud").value=data.budget||"";
function esc(x){return x.replace(/[&<>"]/g,function(c){return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]})}
function draw(){
 var m=$("mon").value,sum=0,by={};
 var rows=data.items.map(function(x,i){x.i=i;return x}).filter(function(x){return x.d.slice(0,7)==m}).sort(function(a,b){return b.d<a.d?-1:1});
 rows.forEach(function(x){sum+=x.a;by[x.c]=(by[x.c]||0)+x.a});
 $("total").textContent=inr(sum)+" spent";
 var b=data.budget||0,mt=$("meter");
 if(b>0){var p=Math.min(100,sum/b*100);mt.style.width=p+"%";mt.style.background=sum>b?"#c53030":(p>80?"#dd6b20":"#38a169");
  $("left").textContent=sum>b?"Over budget by "+inr(sum-b):inr(b-sum)+" left of "+inr(b)}
 else{mt.style.width="0";$("left").textContent="Set a budget to see what is left."}
 var h="";Object.keys(by).sort(function(a,z){return by[z]-by[a]}).forEach(function(k){
  h+="<div class='row' style='justify-content:space-between'><span>"+k+"</span><span>"+inr(by[k])+"</span></div><div class='track'><div class='bar' style='width:"+(by[k]/sum*100)+"%'></div></div>"});
 $("cats").innerHTML=h||"<span class='muted'>Nothing yet.</span>";
 $("list").innerHTML=rows.map(function(x){return "<tr><td>"+x.d.slice(8)+"/"+x.d.slice(5,7)+"</td><td>"+x.c+"</td><td>"+esc(x.n)+"</td><td class='r'>"+inr(x.a)+"</td><td class='r'><button class='x' data-i='"+x.i+"'>✕</button></td></tr>"}).join("")||"<tr><td class='muted'>No entries.</td></tr>";
}
$("add").onclick=function(){
 var a=parseFloat($("a").value);
 if(!(a>0)||!$("d").value)return;
 data.items.push({d:$("d").value,c:$("c").value,n:$("n").value,a:a});
 $("a").value="";$("n").value="";$("mon").value=$("d").value.slice(0,7);
 save();draw();
};
$("list").onclick=function(e){var i=e.target.getAttribute("data-i");if(i===null)return;data.items.splice(+i,1);save();draw()};
$("bud").oninput=function(){data.budget=parseFloat($("bud").value)||0;save();draw()};
$("mon").onchange=draw;
draw();
</script></body></html>
```

